function actions(on){['#speakResult','#copyResult','#savePhrase','#reportTranslation'].forEach(s=>{if($(s))$(s).disabled=!on;});}
function invalidate(){current=null;actions(false);if($('#translationResult'))$('#translationResult').textContent='Translation out of date. Press Translate.';}
function setSpeechUi(active){const start=$('#listenInput'),live=$('#voiceActive');if(start){start.hidden=active;start.setAttribute('aria-pressed',String(active));}if(live)live.hidden=!active;if(active)$('#finishSpeaking')?.focus();}
function writeSpeech(interim=''){const input=$('#sourceText');if(!input)return;const spoken=(speechFinal+' '+interim).trim(),separator=speechBase&&spoken?' ':'',limit=Number(input.maxLength)||500;input.value=(speechBase+separator+spoken).slice(0,limit);$('#characterCount').textContent=input.value.length;invalidate();}
function completeSpeech(){const input=$('#sourceText');speechRecognition=null;speechListening=false;setSpeechUi(false);if(speechHeard&&speechLowestConfidence<.55&&!confirm('Voice confidence is low. Use this message anyway?')){input.value=speechBase;$('#characterCount').textContent=input.value.length;}else if(speechHeard&&speechLowestConfidence<.7){track('low_confidence',$('#sourceLanguage').value,translationScenario,'',speechLowestConfidence);}invalidate();$('#listenInput')?.focus();}
function startRecognition(lang){if(lang==='auto'){toast('Choose the spoken language before using the microphone. Text messages can still use automatic detection.');$('#sourceLanguage')?.focus();return;}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Speech recognition is unavailable in this browser.');return;}translationScenario='culture';speechBase=$('#sourceText').value.trim();speechFinal='';speechLowestConfidence=1;speechHeard=false;const r=new SR();speechRecognition=r;speechListening=true;r.lang=locales[lang];r.continuous=true;r.interimResults=true;r.onstart=()=>setSpeechUi(true);r.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const result=e.results[i],part=result[0];if(result.isFinal){speechFinal=(speechFinal+' '+part.transcript).trim();speechHeard=true;if(Number.isFinite(part.confidence)&&part.confidence>0)speechLowestConfidence=Math.min(speechLowestConfidence,part.confidence);}else interim+=' '+part.transcript;}writeSpeech(interim.trim());};r.onerror=e=>{if(e.error==='aborted'&&!speechListening)return;speechListening=false;toast(e.error==='not-allowed'||e.error==='service-not-allowed'?'Allow microphone access to start speaking.':'Voice input was unclear. Try again.');};r.onend=()=>{if(speechListening){try{r.start();return;}catch(e){speechListening=false;}}if(speechRecognition===r)completeSpeech();};setSpeechUi(true);try{r.start();}catch(e){speechListening=false;completeSpeech();toast('Voice input was unclear. Try again.');}}
function finishRecognition(){if(!speechListening)return;speechListening=false;try{speechRecognition?.stop();}catch(e){completeSpeech();}}
async function translate(){const text=$('#sourceText').value.trim(),from=$('#sourceLanguage').value,to=$('#targetLanguage').value,scenario=translationScenario;if(!text){toast('Enter a message first.');return;}const button=$('#translateButton');button.disabled=true;button.textContent='Translating…';try{let data;const local=(dictionary[from+'-'+to]||{})[text.toLowerCase()];if(local)data={translation:local,detected_language:from,confidence:1,confidence_source:'curated_phrase',alternatives:[],suggestions:[],matched_terms:[]};else{const r=await jsonFetch('api/translate.php',{method:'POST',body:JSON.stringify({text,from,to,scenario})});if(!r.ok)throw new Error(await message(r,'Translation failed.'));data=await r.json();}const confidence=data.confidence===null||data.confidence===undefined?null:Number(data.confidence);current={source:text,translation:data.translation,from:data.detected_language||from,to,scenario,confidence,confidenceSource:data.confidence_source||'',alternatives:data.alternatives||[],suggestions:data.suggestions||[],matchedTerms:data.matched_terms||[]};$('#translationResult').textContent=current.translation;$('#translationMeta').textContent='Detected: '+(names[current.from]||current.from)+' · '+window.JomCore.confidenceLabel(confidence);const context=[...current.alternatives,...current.suggestions.map(v=>v.source_text+' → '+v.translated_text+(v.suggested_reply?' · Reply: '+v.suggested_reply:''))];$('#translationAlternatives').innerHTML=context.length?'<strong>Alternative / scenario context</strong>'+context.map(v=>'<div class="record-item">'+escapeHtml(v)+'</div>').join(''):'';actions(true);renderTwoWay();addConversation(current);if($('#historyConsent')?.checked!==false)await saveRecord({record_type:'translation',title:text,content:current.translation,source_language:current.from,target_language:to,scenario,confidence,metadata:{from:current.from,to,scenario}});await track('translation',to,scenario,current.matchedTerms[0]||'',confidence);prepareNextTwoWayTurn(current,from);if($('#profileVoice')?.checked)await speak();}catch(e){$('#translationResult').textContent=e.message;toast(e.message);}finally{button.disabled=false;button.textContent='Translate message';}}
function renderTwoWay(){const e=$('#twoWayReplies');if(!e)return;if(!$('#twoWayMode').checked||!current){e.innerHTML='';return;}const replies=['Yes, please.','No, thank you.','Could you repeat that?'];e.innerHTML=replies.map(v=>'<button class="chip" data-reply="'+escapeHtml(v)+'">'+escapeHtml(v)+'</button>').join('');$$('[data-reply]').forEach(b=>b.onclick=()=>{const direction={source:current.to,target:current.from};$('#sourceText').value=b.dataset.reply;$('#characterCount').textContent=b.dataset.reply.length;$('#sourceLanguage').value=direction.source;$('#targetLanguage').value=direction.target;invalidate();translate();});}
